const items = $input.all();

return items.map(item => {
  // استخراج القيم من خصائص Notion (عدّل المسميات حسب أسماء العناوين عندك في Notion)
  const props = item.json.properties || {};

  const postName = props['Post Name/ID']?.title[0]?.plain_text || 'Untitled';
  const postType = props['Post Type']?.select?.name || 'Unknown';
  const reach = props['Reach']?.number || 1; // لتجنب القسمة على صفر
  const likes = props['Likes']?.number || 0;
  const comments = props['Comments']?.number || 0;
  const shares = props['Shares']?.number || 0;
  const saves = props['Saves']?.number || 0;
  const hook = props['Caption / Hook']?.rich_text[0]?.plain_text || '';

  const totalInteractions = likes + comments + shares + saves;
  const engagementRate = ((totalInteractions / reach) * 100).toFixed(2);

  return {
    json: {
      postName,
      postType,
      reach,
      likes,
      comments,
      shares,
      saves,
      totalInteractions,
      engagementRate: parseFloat(engagementRate),
      hook
    }
  };
});

